// 同时仍然并发启动 N 个任务，保留 启动重置 / 参数 N / 结束打印 n=<值> 三条行为。
const fixedLines = [
  "const fs = require('fs');",
  "const path = require('path');",
  "",
  "const N = parseInt(process.argv[2], 10) || 0;",
  "const counterFile = path.join(__dirname, 'counter.json');",
  "const logFile = path.join(__dirname, 'log.txt');",
  "",
  "// 契约 1：启动时重置",
  "fs.writeFileSync(counterFile, JSON.stringify({ n: 0 }));",
  "fs.writeFileSync(logFile, '');",
  "",
  "// 单写者串行队列：读-改-写整体原子化",
  "let tail = Promise.resolve();",
  "function serialize(fn) {",
  "  const next = tail.then(fn, fn);",
  "  tail = next.then(function () {}, function () {});",
  "  return next;",
  "}",
  "",
  "function increment(i) {",
  "  return serialize(function () {",
  "    const n = JSON.parse(fs.readFileSync(counterFile, 'utf8')).n + 1;",
  "    fs.writeFileSync(counterFile, JSON.stringify({ n: n }));",
  "    fs.appendFileSync(logFile, 'task ' + i + ' -> n=' + n + '\\n');",
  "  });",
  "}",
  "",
  "// 契约 2：并发启动 N 个任务",
  "(async function () {",
  "  const jobs = [];",
  "  for (let i = 0; i < N; i++) jobs.push(increment(i));",
  "  await Promise.all(jobs);",
  "  // 契约 3：结束时打印 n=<值>",
  "  const n = JSON.parse(fs.readFileSync(counterFile, 'utf8')).n;",
  "  console.log('n=' + n);",
