} catch (e) {
  console.log('no original run.js:', e.message);
}

// 2) 重写为单写者 + 互斥队列：自增任务仍在并发启动，但读改写被串行化
const newRun = [
  "const fs = require('fs');",
  "const path = require('path');",
  "",
  "const N = parseInt(process.argv[2] || '0', 10);",
  "const counterPath = path.join(__dirname, 'counter.json');",
  "const logPath = path.join(__dirname, 'log.txt');",
  "",
  "// 启动时重置（保留原契约）",
  "fs.writeFileSync(counterPath, JSON.stringify({ n: 0 }));",
  "fs.writeFileSync(logPath, '');",
  "",
  "// 互斥队列：所有对 counter.json 的读-改-写串行执行，杜绝丢更新",
  "let lock = Promise.resolve();",
  "function withLock(fn) {",
  "  const run = lock.then(() => fn());",
  "  lock = run.then(() => {}, () => {});",
  "  return run;",
  "}",
  "",
  "function incr() {",
  "  const cur = JSON.parse(fs.readFileSync(counterPath, 'utf8')).n;",
  "  const next = cur + 1;",
  "  fs.writeFileSync(counterPath, JSON.stringify({ n: next }));",
  "  return next;",
  "}",
  "",
  "function task(i) {",
  "  return withLock(() => {",
  "    const n = incr();",
  "    return fs.promises.appendFile(logPath, 'task ' + i + ' -> n=' + n + '\\n');",
  "  });",
  "}",
  "",
  "(async () => {",
  "  await Promise.all(Array.from({ length: N }, (_, i) => task(i)));",
  "  const finalN = JSON.parse(fs.readFileSync(counterPath, 'utf8')).n;",
  "  console.log('n=' + finalN);",
  "})().catch((e) => { console.error(e); process.exit(1); });",
  ""
].join('\n');

