// 1) 只按 \\n 切行；文件末尾的换行只作为行终止符，不产生额外空行（末尾单个空元素丢弃）。
// 2) 行尾 \\r 仅剥离后再判定（容忍 CRLF）；除此之外不对行内容做 trim 或任何规整。
// 3) "恰好 4 个空格分隔字段"：line.split(' ') 必须恰好得到 4 个字段，且 4 个字段均非空
//    （连续空格 / 制表符 / 前导空格 → 字段数不为 4 或出现空字段 → skipped）。
// 4) "第 4 个字段是数字"：按 /^\\d+$/ 判定（非负整数，无正负号，无小数点）。
// 5) 不满足 3) 或 4) 的整行计入 skipped，不参与 total / errors / topPath / p95。
// 6) 状态码字段本身不做格式校验，仅用于 >= 400 比较。
// 歧义点（按最窄解释实现，已报备）：
//   - 连续空格 / 制表符分隔 → 不满足"恰好 4 字段" → skipped
//   - total === 0 时 p95=0、topPath='' （本样例 total=6，不触发；如需约定请确认）

const fs = require('fs');

const raw = fs.readFileSync('access.log', 'utf8');
let lines = raw.split('\\n');
if (lines.length > 0 && lines[lines.length - 1] === '') lines = lines.slice(0, -1);

let total = 0;
let skipped = 0;
let errors = 0;
const pathCount = new Map();
const durations = [];

for (let i = 0; i < lines.length; i++) {
  let line = lines[i];
  if (line.endsWith('\\r')) line = line.slice(0, -1);

  const parts = line.split(' ');
  const valid = parts.length === 4 && parts.every((p) => p.length > 0) && /^\\d+$/.test(parts[3]);
  if (!valid) {
    skipped++;
    continue;
  }

  total++;
  const status = Number(parts[2]);
  if (status >= 400) errors++;

  const p = parts[1];
  pathCount.set(p, (pathCount.get(p) || 0) + 1);
  durations.push(Number(parts[3]));
}

let topPath = '';
if (total > 0) {
  const entries = Array.from(pathCount.entries()).sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1];
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0;
  });
  topPath = entries[0][0];
}

let p95 = 0;
if (total > 0) {
  durations.sort((a, b) => a - b);
  p95 = durations[Math.ceil(0.95 * total) - 1];
}

process.stdout.write(JSON.stringify({ total, skipped, errors, topPath, p95 }) + '\\n');
`;
