const fs = require('fs');
const path = require('path');

const COUNTER = path.join(__dirname, 'counter.json');
const LOG = path.join(__dirname, 'log.txt');

const N = Number.parseInt(process.argv[2], 10);
if (!Number.isInteger(N) || N < 0) {
  process.stderr.write('usage: node run.js N\n');
  process.exit(1);
}

// CLI contract: reset state at startup
fs.writeFileSync(COUNTER, JSON.stringify({ n: 0 }));
fs.writeFileSync(LOG, '');

// FIX: single-writer queue. Every read-modify-write of counter.json runs
// inside this promise chain, so no two tasks can interleave read and write.
let tail = Promise.resolve();
function serialize(fn) {
  const run = tail.then(fn, fn);
  tail = run.then(() => {}, () => {});
  return run;
}

function task(i) {
  return serialize(() => new Promise((resolve, reject) => {
    let cur;
    try { cur = JSON.parse(fs.readFileSync(COUNTER, 'utf8')); }
    catch (e) { return reject(e); }
    // the original race window (yield between read and write) is kept,
    // but the whole section is serialized so it can no longer interleave.
    setImmediate(() => {
      try {
        const next = { n: cur.n + 1 };
        fs.writeFileSync(COUNTER, JSON.stringify(next));
        fs.appendFileSync(LOG, 'task ' + i + ' -> n=' + next.n + '\n');
        resolve(next.n);
      } catch (e) { reject(e); }
    });
  }));
}

const jobs = [];
for (let i = 0; i < N; i++) jobs.push(task(i));
